create table if not exists public.guardian_relationships(id uuid primary key default gen_random_uuid(),learner_id uuid not null references public.profiles(id) on delete cascade,guardian_user_id uuid references public.profiles(id) on delete set null,guardian_email text,guardian_phone text,relationship text not null,status text not null default 'pending' check(status in ('pending','verified','rejected','revoked')),consent_version text,requested_at timestamptz not null default now(),verified_at timestamptz,verified_by uuid references public.profiles(id) on delete set null,notes text,unique(learner_id,guardian_email));
create index if not exists guardian_relationships_learner_idx on public.guardian_relationships(learner_id,status);

create table if not exists public.sector_partner_registration_requests(id uuid primary key default gen_random_uuid(),requested_by uuid not null references public.profiles(id) on delete cascade,partner_type_key text not null references public.sector_partner_types(partner_type_key),organization_name text not null,website text,contact_email text,description text,status text not null default 'pending' check(status in ('pending','approved','rejected','cancelled')),review_notes text,reviewed_by uuid references public.profiles(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists sector_partner_one_pending_request_uidx on public.sector_partner_registration_requests(requested_by) where status='pending';
create table if not exists public.sector_partner_organizations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete restrict,partner_type_key text not null references public.sector_partner_types(partner_type_key),organization_name text not null,website text,contact_email text,description text,verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected','suspended')),verified_by uuid references public.profiles(id) on delete set null,verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists sector_partner_org_type_idx on public.sector_partner_organizations(partner_type_key,verification_status);
create table if not exists public.sector_partner_members(partner_organization_id uuid not null references public.sector_partner_organizations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,member_role text not null default 'member' check(member_role in ('owner','admin','member','analyst')),status text not null default 'active' check(status in ('active','invited','suspended')),created_at timestamptz not null default now(),primary key(partner_organization_id,user_id));

alter table public.guardian_relationships enable row level security;alter table public.sector_partner_registration_requests enable row level security;alter table public.sector_partner_organizations enable row level security;alter table public.sector_partner_members enable row level security;
create policy guardian_relationships_read on public.guardian_relationships for select to authenticated using(learner_id=(select auth.uid()) or guardian_user_id=(select auth.uid()) or private.is_admin_user());
create policy guardian_relationships_insert on public.guardian_relationships for insert to authenticated with check(learner_id=(select auth.uid()));
create policy guardian_relationships_update_admin on public.guardian_relationships for update to authenticated using(private.is_admin_user()) with check(private.is_admin_user());
create policy partner_registration_read on public.sector_partner_registration_requests for select to authenticated using(requested_by=(select auth.uid()) or private.is_admin_user());
create policy partner_registration_insert on public.sector_partner_registration_requests for insert to authenticated with check(requested_by=(select auth.uid()) and status='pending');
create policy partner_registration_update on public.sector_partner_registration_requests for update to authenticated using((requested_by=(select auth.uid()) and status='pending') or private.is_admin_user()) with check((requested_by=(select auth.uid()) and status in ('pending','cancelled')) or private.is_admin_user());
create policy sector_partner_org_read on public.sector_partner_organizations for select to authenticated using(verification_status='verified' or owner_id=(select auth.uid()) or private.is_admin_user() or exists(select 1 from public.sector_partner_members m where m.partner_organization_id=id and m.user_id=(select auth.uid()) and m.status='active'));
create policy sector_partner_org_update on public.sector_partner_organizations for update to authenticated using(owner_id=(select auth.uid()) or private.is_admin_user()) with check(owner_id=(select auth.uid()) or private.is_admin_user());
create policy sector_partner_members_read on public.sector_partner_members for select to authenticated using(user_id=(select auth.uid()) or private.is_admin_user() or exists(select 1 from public.sector_partner_members me where me.partner_organization_id=partner_organization_id and me.user_id=(select auth.uid()) and me.member_role in ('owner','admin') and me.status='active'));
create policy mela_gate_platform_live on public.guardian_relationships as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.sector_partner_registration_requests as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.sector_partner_organizations as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));create policy mela_gate_platform_live on public.sector_partner_members as restrictive for all to anon,authenticated using(public.platform_feature_available('platform_live')) with check(public.platform_feature_available('platform_live'));
revoke all on public.guardian_relationships,public.sector_partner_registration_requests,public.sector_partner_organizations,public.sector_partner_members from anon,authenticated;grant select,insert on public.guardian_relationships to authenticated;grant select,insert,update on public.sector_partner_registration_requests to authenticated;grant select,update on public.sector_partner_organizations to authenticated;grant select on public.sector_partner_members to authenticated;

create or replace function public.request_my_guardian_consent(p_guardian_email text,p_relationship text,p_guardian_phone text default null) returns public.guardian_relationships language plpgsql security invoker set search_path to '' as $function$ declare v_uid uuid:=(select auth.uid());v public.guardian_relationships%rowtype;v_stage text;begin if v_uid is null then raise exception 'authentication required';end if;select education_stage_key into v_stage from public.profiles where id=v_uid and role='student';if v_stage not like 'school_%' then raise exception 'guardian workflow is only for school-stage learner accounts';end if;if nullif(trim(coalesce(p_guardian_email,'')),'') is null then raise exception 'guardian email is required';end if;if nullif(trim(coalesce(p_relationship,'')),'') is null then raise exception 'relationship is required';end if;insert into public.guardian_relationships(learner_id,guardian_email,guardian_phone,relationship,status,consent_version) values(v_uid,lower(trim(p_guardian_email)),nullif(trim(coalesce(p_guardian_phone,'')),''),trim(p_relationship),'pending','2026-08-14') on conflict(learner_id,guardian_email) do update set guardian_phone=excluded.guardian_phone,relationship=excluded.relationship,status='pending',requested_at=now(),verified_at=null,verified_by=null returning * into v;return v;end;$function$;
create or replace function public.review_guardian_consent(p_relationship_id uuid,p_decision text,p_notes text default null) returns public.guardian_relationships language plpgsql security invoker set search_path to '' as $function$ declare v_uid uuid:=(select auth.uid());v public.guardian_relationships%rowtype;begin if not private.is_admin_user() then raise exception 'admin required';end if;if p_decision not in ('verified','rejected') then raise exception 'decision must be verified or rejected';end if;update public.guardian_relationships set status=p_decision,verified_at=case when p_decision='verified' then now() else null end,verified_by=v_uid,notes=nullif(trim(coalesce(p_notes,'')),'') where id=p_relationship_id returning * into v;if not found then raise exception 'guardian relationship not found';end if;if p_decision='verified' then update public.profiles set learner_safety_status='guardian_verified',updated_at=now() where id=v.learner_id;end if;return v;end;$function$;

create or replace function public.request_sector_partner_registration(p_partner_type_key text,p_organization_name text,p_website text default null,p_contact_email text default null,p_description text default null) returns public.sector_partner_registration_requests language plpgsql security invoker set search_path to '' as $function$ declare v_uid uuid:=(select auth.uid());v public.sector_partner_registration_requests%rowtype;begin if v_uid is null then raise exception 'authentication required';end if;if not exists(select 1 from public.sector_partner_types where partner_type_key=p_partner_type_key) then raise exception 'unsupported partner type';end if;if nullif(trim(coalesce(p_organization_name,'')),'') is null then raise exception 'organization name is required';end if;insert into public.sector_partner_registration_requests(requested_by,partner_type_key,organization_name,website,contact_email,description) values(v_uid,p_partner_type_key,trim(p_organization_name),nullif(trim(coalesce(p_website,'')),''),nullif(lower(trim(coalesce(p_contact_email,''))),''),nullif(trim(coalesce(p_description,'')),'')) returning * into v;return v;end;$function$;
create or replace function private.process_sector_partner_registration(p_request_id uuid,p_decision text,p_notes text default null) returns public.sector_partner_registration_requests language plpgsql security definer set search_path to '' as $function$ declare v_uid uuid:=(select auth.uid());r public.sector_partner_registration_requests%rowtype;o public.sector_partner_organizations%rowtype;begin if not private.is_admin_user() then raise exception 'admin required';end if;if p_decision not in ('approved','rejected') then raise exception 'decision must be approved or rejected';end if;select * into r from public.sector_partner_registration_requests where id=p_request_id for update;if not found or r.status<>'pending' then raise exception 'pending request required';end if;update public.sector_partner_registration_requests set status=p_decision,review_notes=nullif(trim(coalesce(p_notes,'')),''),reviewed_by=v_uid,reviewed_at=now(),updated_at=now() where id=r.id returning * into r;if p_decision='approved' then insert into public.sector_partner_organizations(owner_id,partner_type_key,organization_name,website,contact_email,description,verification_status,verified_by,verified_at) values(r.requested_by,r.partner_type_key,r.organization_name,r.website,r.contact_email,r.description,'verified',v_uid,now()) returning * into o;insert into public.sector_partner_members(partner_organization_id,user_id,member_role,status) values(o.id,r.requested_by,'owner','active') on conflict do nothing;update public.profiles set role='partner',updated_at=now() where id=r.requested_by;update auth.users set raw_app_meta_data=coalesce(raw_app_meta_data,'{}'::jsonb)||jsonb_build_object('role','partner') where id=r.requested_by;end if;return r;end;$function$;
revoke all on function private.process_sector_partner_registration(uuid,text,text) from public,anon,authenticated;
create or replace function public.review_sector_partner_registration(p_request_id uuid,p_decision text,p_notes text default null) returns public.sector_partner_registration_requests language sql security invoker set search_path to '' as $function$ select * from private.process_sector_partner_registration(p_request_id,p_decision,p_notes); $function$;
create or replace function public.get_my_partner_dashboard() returns jsonb language sql stable security invoker set search_path to '' as $function$ with me as(select * from public.profiles where id=(select auth.uid())),org as(select o.* from public.sector_partner_organizations o join public.sector_partner_members m on m.partner_organization_id=o.id where m.user_id=(select auth.uid()) and m.status='active' order by (m.member_role='owner') desc,o.created_at limit 1) select jsonb_build_object('profile',to_jsonb(me),'organization',to_jsonb(org),'partner_type',(select to_jsonb(t) from public.sector_partner_types t join org on org.partner_type_key=t.partner_type_key),'sections',(select coalesce(jsonb_agg(jsonb_build_object('section_key',s.section_key,'title',s.title,'description',s.description,'subsections',(select coalesce(jsonb_agg(jsonb_build_object('subsection_key',ss.subsection_key,'title',ss.title,'description',ss.description,'route_key',ss.route_key) order by ss.display_order),'[]'::jsonb) from public.platform_audience_subsections ss,org where ss.section_key=s.section_key and ss.active and org.partner_type_key=any(ss.target_partner_types))) order by s.display_order),'[]'::jsonb) from public.platform_audience_sections s where s.audience_group='partner' and s.active)) from me left join org on true; $function$;
grant execute on function public.request_my_guardian_consent(text,text,text),public.review_guardian_consent(uuid,text,text),public.request_sector_partner_registration(text,text,text,text,text),public.review_sector_partner_registration(uuid,text,text),public.get_my_partner_dashboard() to authenticated;
